import sys

def count_returnable_rooms(t, test_cases):
    results = []
    for n, s in test_cases:
        returnable_count = 0
        for start in range(n):
            current = start
            visited = set()
            while True:
                if current in visited:
                    break
                visited.add(current)
                if s[current] == '>':
                    current = (current + 1) % n
                elif s[current] == '<':
                    current = (current - 1) % n
                else:
                    # Try both directions
                    next1 = (current + 1) % n
                    next2 = (current - 1) % n
                    if next1 not in visited:
                        current = next1
                    elif next2 not in visited:
                        current = next2
                    else:
                        break
            if current == start:
                returnable_count += 1
        results.append(returnable_count)
    return results

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    test_cases = []
    index = 1
    for _ in range(t):
        n = int(data[index])
        s = data[index + 1]
        test_cases.append((n, s))
        index += 2

    results = count_returnable_rooms(t, test_cases)
    for result in results:
        print(result)

